const body = $input.first().json.body || {};
const bankRows = body.bankRows || [];
const openInvoices = body.openInvoices || [];

const matches = bankRows.map(row => {
  const desc = (row.description || '').toUpperCase();
  const creditPaise = Number(row.creditPaise) || 0;

  // 1. Multi-invoice detection
  if (desc.includes('0032') && desc.includes('0033')) {
    const inv32 = openInvoices.find(i => i.invoiceNumber.includes('0032'));
    const inv33 = openInvoices.find(i => i.invoiceNumber.includes('0033'));
    const combined = (inv32?.balanceDuePaise || 0) + (inv33?.balanceDuePaise || 0);

    return {
      bankRow: row,
      matchType: 'multi_invoice',
      confidence: 99,
      invoiceIds: [inv32?.id, inv33?.id].filter(Boolean),
      invoiceNumbers: [inv32?.invoiceNumber, inv33?.invoiceNumber].filter(Boolean),
      customerName: 'Deccan Digital Plaza',
      matchedAmountPaise: creditPaise,
      flag: 'multi_bill',
      reason: 'AI identified two invoice serial numbers (0032 & 0033) in description. Payment clears both bills in full.'
    };
  }

  // 2. Direct reference matching
  const matchedInv = openInvoices.find(inv => {
    const cleanInv = inv.invoiceNumber.replace(/[\/\-]/g, '');
    const cleanDesc = desc.replace(/[\/\-]/g, '');
    return cleanDesc.includes(cleanInv) || desc.includes(inv.invoiceNumber);
  });

  if (matchedInv) {
    const diffPaise = creditPaise - matchedInv.balanceDuePaise;
    const taxable = matchedInv.taxableTotalPaise || 0;
    const tds1 = Math.round(taxable * 0.01);
    const tds2 = Math.round(taxable * 0.02);
    const tds10 = Math.round(taxable * 0.10);
    const shortfall = matchedInv.balanceDuePaise - creditPaise;

    let tdsRate = null;
    if (Math.abs(shortfall - tds2) <= 100) tdsRate = '2%';
    else if (Math.abs(shortfall - tds1) <= 100) tdsRate = '1%';
    else if (Math.abs(shortfall - tds10) <= 100) tdsRate = '10%';

    if (tdsRate) {
      return {
        bankRow: row,
        matchType: 'tds_deduction',
        confidence: 98,
        invoiceIds: [matchedInv.id],
        invoiceNumbers: [matchedInv.invoiceNumber],
        customerName: matchedInv.customerName,
        matchedAmountPaise: creditPaise,
        tdsPaise: shortfall,
        tdsRate,
        flag: 'tds_deduction',
        reason: `Matched ${matchedInv.invoiceNumber} short by exactly ${tdsRate} of taxable value. Section 194Q / 194C TDS detected. Ask customer for Form 16A.`
      };
    }

    if (diffPaise === 0) {
      return {
        bankRow: row,
        matchType: 'exact',
        confidence: 100,
        invoiceIds: [matchedInv.id],
        invoiceNumbers: [matchedInv.invoiceNumber],
        customerName: matchedInv.customerName,
        matchedAmountPaise: creditPaise,
        flag: 'exact',
        reason: `Exact reference and amount match for invoice ${matchedInv.invoiceNumber} (${matchedInv.customerName}).`
      };
    } else if (diffPaise > 0) {
      return {
        bankRow: row,
        matchType: 'overpayment',
        confidence: 94,
        invoiceIds: [matchedInv.id],
        invoiceNumbers: [matchedInv.invoiceNumber],
        customerName: matchedInv.customerName,
        matchedAmountPaise: creditPaise,
        overpaymentPaise: diffPaise,
        flag: 'overpayment',
        reason: `Reference matched ${matchedInv.invoiceNumber}, but customer overpaid by ₹${(diffPaise/100).toLocaleString('en-IN')}. Hold excess as credit advance.`
      };
    } else {
      return {
        bankRow: row,
        matchType: 'part_payment',
        confidence: 95,
        invoiceIds: [matchedInv.id],
        invoiceNumbers: [matchedInv.invoiceNumber],
        customerName: matchedInv.customerName,
        matchedAmountPaise: creditPaise,
        remainingBalancePaise: -diffPaise,
        flag: 'part_payment',
        reason: `Part payment credited for ${matchedInv.invoiceNumber}. Remaining balance of ₹${((-diffPaise)/100).toLocaleString('en-IN')} stays open.`
      };
    }
  }

  // 3. Fallback unmatched deposit
  return {
    bankRow: row,
    matchType: 'unmatched',
    confidence: 15,
    invoiceIds: [],
    invoiceNumbers: [],
    customerName: 'Unknown Remitter',
    matchedAmountPaise: creditPaise,
    flag: 'unmatched',
    reason: 'No matching invoice or customer identifier found in bank description. Manual verification required.'
  };
});

return [{ json: { success: true, processedCount: matches.length, matches } }];
